  match r, ph with
  | 1, 0 => farm1_0_1RB1LD_0LC1RB_1LA0RB_1LC0RB
  | _, _ => farm1_0_1RB1LD_0LC1RB_1LA0RB_1LC0RB  (* unreachable: 0 < r < N0 + st *)
  end.

