  | 2, 1 => iarm2_1_1RB1RB_1LC1RD_0RD1LB_0RA0LC
  | _, _ => iarm0_0_1RB1RB_1LC1RD_0RD1LB_0RA0LC   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

